"""Reviewed reachability, shortest paths, small-state enumeration and trees."""
from nowcoder_editorials import CONTENT, add, read, register
from nowcoder_dsu_support import DSU


def run():
    existing = read(CONTENT / 'reviewed.json')
    def put(n, *args, **kwargs):
        if f'nowcoder-global::{n}' not in existing:
            add(n, *args, **kwargs)
    put(14572, 1000, ['广度优先搜索', '网格'], '判断四方向移动能否从S到E，不能通过井号格。',
        '从S开始BFS，把所有尚未访问且不是障碍的相邻格入队。每个格只入队一次，搜索结束检查E是否被访问。只求存在性，深搜也可以，但大地图用队列避免递归栈过深。',
        r'''int n, m; while (cin >> n >> m) { vector<string> grid(n); int start = -1, target = -1; for (int r = 0; r < n; r++) { cin >> grid[r]; for (int c = 0; c < m; c++) { if (grid[r][c] == 'S') start = r * m + c; if (grid[r][c] == 'E') target = r * m + c; } } vector<bool> seen(n * m); vector<int> queue{start}; seen[start] = true; const int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1}; for (size_t head = 0; head < queue.size(); head++) { int r = queue[head] / m, c = queue[head] % m; for (int d = 0; d < 4; d++) { int rr = r + dr[d], cc = c + dc[d]; if (rr >= 0 && rr < n && cc >= 0 && cc < m && grid[rr][cc] != '#' && !seen[rr * m + cc]) { seen[rr * m + cc] = true; queue.push_back(rr * m + cc); } } } cout << (seen[target] ? "Yes\n" : "No\n"); }''',
        '多组输入直到EOF。入队时标记，避免同一格被多个方向重复入队。', complexity=r'每组时间、空间均为 $O(nm)$。')
    put(14698, 1800, ['连通分量', '贪心'], '攻击引发八邻域连锁爆炸，双方轮流攻击，求清空敌军后最多剩余己方炮数。',
        '每张4行地图中，八邻接的大炮连通块会被一次攻击全部摧毁。设敌军有 k 块，则必须攻击 k 次，前 k−1 次后敌军会反击并摧毁我方当前开炮所在块，最后一次敌军清空，不会反击。故我方至少需要 k 块；为损失最少，前 k−1 次依次牺牲最小的块，最后用任意剩余块开炮。若敌军本来为空无需攻击；我方块数不足则不可能。',
        r'''int m; cin >> m; auto components = [&]() { vector<string> grid(4); for (auto &row : grid) cin >> row; vector<int> sizes; for (int r = 0; r < 4; r++) for (int c = 0; c < m; c++) if (grid[r][c] == '*') { vector<pair<int,int>> queue{{r,c}}; grid[r][c] = '.'; for (size_t head = 0; head < queue.size(); head++) { auto [x,y] = queue[head]; for (int dx = -1; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) { int xx = x + dx, yy = y + dy; if (xx >= 0 && xx < 4 && yy >= 0 && yy < m && grid[xx][yy] == '*') { grid[xx][yy] = '.'; queue.push_back({xx,yy}); } } } sizes.push_back(queue.size()); } return sizes; }; auto enemy = components(); auto ours = components(); int k = enemy.size(), answer = accumulate(ours.begin(),ours.end(),0); if (k > (int)ours.size()) cout << -1; else { sort(ours.begin(),ours.end()); for (int i = 0; i < k - 1; i++) answer -= ours[i]; cout << answer; }''',
        '输入前四行是司机，后四行才是齐齐。连锁按八方向相邻，最后一击后没有反击。', complexity=r'时间 $O(m\log m)$，空间 $O(m)$。')
    put(201613, 1100, ['广度优先搜索', '三维网格'], '在三维果冻中六方向移动，求从首格到末格最少吃的块数。',
        '将坐标压成 (x*n+y)*n+z，BFS求最少步数。起点也要吃一块，所以起点距离初始化为1；每移动一次加1。星号不能进入，终点没访问到则输出−1。',
        r'''int n; cin >> n; int size = n * n * n; vector<char> grid(size); for (int i = 0; i < size; i++) cin >> grid[i]; vector<int> distance(size,-1), queue{0}; distance[0] = 1; int dx[] = {1,-1,0,0,0,0}, dy[] = {0,0,1,-1,0,0}, dz[] = {0,0,0,0,1,-1}; for (size_t head = 0; head < queue.size(); head++) { int u = queue[head], x = u / (n * n), y = u / n % n, z = u % n; for (int d = 0; d < 6; d++) { int a = x + dx[d], b = y + dy[d], c = z + dz[d]; if (a < 0 || a >= n || b < 0 || b >= n || c < 0 || c >= n) continue; int v = (a * n + b) * n + c; if (grid[v] != '*' && distance[v] == -1) { distance[v] = distance[u] + 1; queue.push_back(v); } } } cout << distance.back();''',
        '输出经过的块数，不是边数；n=1时答案为1。', complexity=r'时间、空间均为 $O(n^3)$。', cases=[{'input':'1\n.','output':'1'}])
    put(16498, 1800, ['反向图', '广度优先搜索'], '路径上的每个点，其全部出边都必须指向原图中能到终点的点，求最短合法路径。',
        '先从终点沿反向边BFS，标出原图中能到终点的集合R。再检查每个点：若存在一条出边指向R之外，该点不能在答案路径中；其余点可用。最后在只允许这些点的原图上从s做BFS。注意合法性依据原图的可达集合R，只筛一次，不能把删除非法点后的不可达性不断向前传递，因为题目并未要求所有分支都沿合法路径到达终点。',
        r'''int n, m; cin >> n >> m; vector<vector<int>> graph(n + 1), reverse(n + 1); while (m--) { int a, b; cin >> a >> b; graph[a].push_back(b); reverse[b].push_back(a); } int s, t; cin >> s >> t; vector<bool> reachable(n + 1), valid(n + 1,true); vector<int> queue{t}; reachable[t] = true; for (size_t h = 0; h < queue.size(); h++) for (int v : reverse[queue[h]]) if (!reachable[v]) { reachable[v] = true; queue.push_back(v); } for (int u = 1; u <= n; u++) for (int v : graph[u]) if (!reachable[v]) valid[u] = false;
        vector<int> distance(n + 1,-1); queue.clear(); if (valid[s]) { queue.push_back(s); distance[s] = 0; } for (size_t h = 0; h < queue.size(); h++) for (int v : graph[queue[h]]) if (valid[v] && distance[v] == -1) { distance[v] = distance[queue[h]] + 1; queue.push_back(v); } cout << distance[t];''',
        '不能只删掉不能到终点的点，还要禁止所有具有坏出边的点。终点无出边，天然合法。', complexity=r'时间、空间均为 $O(n+m)$。')
    put(13224, 2100, ['反向图', '贪心', '环检测'], '可正负跳跃，到达末点的选择串按a小于b取字典序最小；无最小有限串时输出Infinity。',
        '对每个合法跳跃建边，反向搜索求能到末点的集合。若0不在其中，输出No solution!。否则从0开始，每一步优先选择仍能到终点的a边，没有才选b；这是字典序的首次不同字符原则。到终点立刻停止，因为空后缀最小。\n\n若在到终点之前重复来到某点，贪心选择将永远重复这一圈。虽然每个点都能绕路到终点，但每次选择退出环的有限串，都能通过再绕一圈得到更小的串，因此没有最小有限答案，输出Infinity!。访问标记可在线检测。',
        r'''int n; cin >> n; vector<array<int,2>> edge(n); vector<vector<int>> reverse(n); for (int type = 0; type < 2; type++) for (int i = 0; i < n; i++) { int step; cin >> step; int v = i + step; edge[i][type] = (v >= 0 && v < n) ? v : -1; if (edge[i][type] != -1) reverse[v].push_back(i); } vector<bool> reachable(n), seen(n); vector<int> queue{n - 1}; reachable[n - 1] = true; for (size_t h = 0; h < queue.size(); h++) for (int v : reverse[queue[h]]) if (!reachable[v]) { reachable[v] = true; queue.push_back(v); } if (!reachable[0]) { cout << "No solution!"; return 0; } int u = 0; string answer; while (u != n - 1) { if (seen[u]) { cout << "Infinity!"; return 0; } seen[u] = true; int a = edge[u][0]; int type = (a != -1 && reachable[a]) ? 0 : 1; answer += char('a' + type); u = edge[u][type]; } cout << answer;''',
        '不是求最短选择串；a自环即使有b出口，也可能导致字典序没有有限最小值。n=1时答案是空串。', complexity=r'时间、空间均为 $O(n)$。', cases=[{'input':'2\n0 0\n1 0','output':'Infinity!'}])
    put(15136, 1400, ['广度优先搜索', '状态建模'], '四方向迷宫，有钥匙后才可经过门，求最少步数。',
        '状态必须包含位置和是否持有钥匙，不能只标记格子。每个格子拆成无钥匙、有钥匙两个状态，经过K后钥匙位变成1，进入D要求钥匙位已经为1，其余合法移动花费1。BFS第一次到达终点的距离即最少步数。',
        r'''int n, m; cin >> n >> m; vector<string> grid(n); int start = 0; for (int r = 0; r < n; r++) { cin >> grid[r]; for (int c = 0; c < m; c++) if (grid[r][c] == 'S') start = (r * m + c) * 2; } vector<int> distance(2 * n * m,-1), queue{start}; distance[start] = 0; int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1}; int answer = -1;
        for (size_t h = 0; h < queue.size(); h++) { int u = queue[h], key = u % 2, r = u / 2 / m, c = u / 2 % m; if (grid[r][c] == 'E') { answer = distance[u]; break; } for (int d = 0; d < 4; d++) { int rr = r + dr[d], cc = c + dc[d]; if (rr < 0 || rr >= n || cc < 0 || cc >= m) continue; char cell = grid[rr][cc]; if (cell == 'W' || (cell == 'D' && !key)) continue; int v = (rr * m + cc) * 2 + (key || cell == 'K'); if (distance[v] == -1) { distance[v] = distance[u] + 1; queue.push_back(v); } } } cout << answer;''',
        '取得钥匙后可以回到以前走过的格子，这是另一状态。门是D，墙是W。', complexity=r'时间、空间均为 $O(nm)$。')
    put(53680, 1300, ['深度优先搜索', '枚举'], '每块石头二选一，财富或魔法低于0就归零，最大化最后乘积。',
        'n最多15，直接DFS枚举每块石头的两种选择。转移时马上把被减少的量截到0，不能把负数留到最后。到第n块后计算乘积取最大。搜索深度只有15，不需要记忆化。',
        r'''int n; cin >> n; vector<array<long long,4>> a(n); for (auto &x : a) for (auto &v : x) cin >> v; long long answer = 0; auto dfs = [&](auto &&self, int i, long long wealth, long long magic) -> void { if (i == n) { answer = max(answer,wealth * magic); return; } auto [gain,cost,recover,loss] = a[i]; self(self,i + 1,wealth + gain,max(0LL,magic - cost)); self(self,i + 1,max(0LL,wealth - loss),magic + recover); }; dfs(dfs,0,0,0); cout << answer;''',
        '每步都归零，不能把减少量当欠债。两个累计量可达一千五百万，乘积用64位。', complexity=r'时间 $O(2^n)$，额外空间 $O(n)$。')
    put(20583, 1900, ['图遍历', '质因数分解', '一致性约束'], '链条约束两齿轮的带符号转速比，判断全部齿轮能否同时非零转动。',
        '每条边u→v要求 speed[v]=speed[u]*y/x。直接连乘浮点数可能溢出或累计误差；由于|x|、|y|≤100，把绝对值分解为25个不超过100的质数的指数，另用一位表示符号。每个连通块任选根转速为1，遍历边时指数向量相加、符号异或。若到达已经赋值的点，要求整向量和符号完全一致；不一致说明环上乘积不是1，无法全部非零转动。不同块可独立选根，不必联系起来。',
        r'''vector<int> primes; for (int p = 2; p <= 100; p++) { bool prime = true; for (int d = 2; d * d <= p; d++) if (p % d == 0) prime = false; if (prime) primes.push_back(p); } array<array<int,25>,101> factor{}; for (int x = 1; x <= 100; x++) { int value = x; for (int j = 0; j < 25; j++) while (value % primes[j] == 0) { factor[x][j]++; value /= primes[j]; } }
        int tests; cin >> tests; for (int tc = 1; tc <= tests; tc++) { int n, m; cin >> n >> m; struct Edge { int to, sign; array<int,25> delta; }; vector<vector<Edge>> graph(n + 1); while (m--) { int u, v, x, y; cin >> u >> v >> x >> y; Edge forward{v,y < 0,{}}, backward{u,y < 0,{}}; for (int j = 0; j < 25; j++) { forward.delta[j] = factor[abs(y)][j] - factor[x][j]; backward.delta[j] = -forward.delta[j]; } graph[u].push_back(forward); graph[v].push_back(backward); } vector<bool> seen(n + 1); vector<int> sign(n + 1); vector<array<int,25>> speed(n + 1); bool valid = true;
        for (int root = 1; root <= n; root++) if (!seen[root]) { vector<int> queue{root}; seen[root] = true; for (size_t h = 0; h < queue.size(); h++) { int u = queue[h]; for (const auto &e : graph[u]) { auto next = speed[u]; for (int j = 0; j < 25; j++) next[j] += e.delta[j]; int nextSign = sign[u] ^ e.sign; if (!seen[e.to]) { seen[e.to] = true; speed[e.to] = next; sign[e.to] = nextSign; queue.push_back(e.to); } else if (speed[e.to] != next || sign[e.to] != nextSign) valid = false; } } } cout << "Case #" << tc << ": " << (valid ? "Yes\n" : "No\n"); }''',
        'y可为负，方向矛盾也会导致系统锁死。检查的是乘法比例，不是普通距离差。指数可为负，表示分母。', complexity=r'每组时间、空间均为 $O(25(n+m))$。')
    put(15291, 1300, ['深度优先搜索', '区间计数'], '幸运数只含4、7，求区间内每个数向上取到首个幸运数后的总和。',
        '生成不超过10位的全部幸运数并排序，其中4444444444已覆盖十亿上界。相邻幸运数previous、value之间，所有整数 (previous,value] 的next都等于value。将该段与[l,r]求交，用交集整数个数乘value累加。无需逐个枚举原区间。',
        r'''long long l, r; cin >> l >> r; vector<long long> lucky; auto dfs = [&](auto &&self, long long x, int digits) -> void { if (digits) lucky.push_back(x); if (digits == 10) return; self(self,x * 10 + 4,digits + 1); self(self,x * 10 + 7,digits + 1); }; dfs(dfs,0,0); sort(lucky.begin(),lucky.end()); long long previous = 0, answer = 0; for (long long value : lucky) { long long left = max(l,previous + 1), right = min(r,value); if (left <= right) answer += (right - left + 1) * value; previous = value; if (value >= r) break; } cout << answer;''',
        '生成的幸运数需要超出r，才能覆盖最后一段；区间包括幸运数本身。答案用64位。', complexity=r'本题最多生成2046个数，记数量为 $K$，时间 $O(K\log K)$，空间 $O(K)$。')
    put(16591, 1800, ['并查集', '贪心', '二分图'], '把罪犯分进两座监狱，使同狱仇恨边的最大权尽量小。',
        '按仇恨值从大到小，尝试把每条边两端强制分到不同监狱。用两倍并查集表示“某人”和“某人的对立阵营”。若处理权值w时两人已经同组，说明所有权值至少w的边不能全跨监狱，答案至少w；此前更大边约束均可满足，故答案恰为w。若所有约束都可满足，整图二分，答案0。',
        r'''int n, m; cin >> n >> m; struct Edge { int a, b, w; }; vector<Edge> edges(m); for (auto &e : edges) cin >> e.a >> e.b >> e.w; sort(edges.begin(),edges.end(),[](auto a, auto b) { return a.w > b.w; }); DSU dsu(2 * n); int answer = 0; for (auto e : edges) { if (dsu.find(e.a) == dsu.find(e.b)) { answer = e.w; break; } dsu.unite(e.a,e.b + n); dsu.unite(e.a + n,e.b); } cout << answer;''',
        '有矛盾时输出当前权值，不是减一。两监狱允许空置，目标只取最大冲突。', declarations=DSU, complexity=r'时间 $O(m\log m+(n+m)\alpha(n))$，空间 $O(n+m)$。')
    put(15434, 1000, ['广度优先搜索', '网格'], '多组迷宫，判断不经过x障碍能否四方向到达t。',
        '从s开始BFS，入队时标记已访问，不重复经过同一格也足以判断存在路径：任何可达路径删掉环后仍可达。访问到t输出YES，否则NO。',
        r'''int tests; cin >> tests; while (tests--) { int n, m; cin >> n >> m; vector<string> grid(n); int start = 0, target = 0; for (int r = 0; r < n; r++) { cin >> grid[r]; for (int c = 0; c < m; c++) { if (grid[r][c] == 's') start = r * m + c; if (grid[r][c] == 't') target = r * m + c; } } vector<bool> seen(n * m); vector<int> queue{start}; seen[start] = true; int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1}; for (size_t h = 0; h < queue.size(); h++) { int r = queue[h] / m, c = queue[h] % m; for (int d = 0; d < 4; d++) { int rr = r + dr[d], cc = c + dc[d]; if (rr >= 0 && rr < n && cc >= 0 && cc < m && grid[rr][cc] != 'x' && !seen[rr * m + cc]) { seen[rr * m + cc] = true; queue.push_back(rr * m + cc); } } } cout << (seen[target] ? "YES\n" : "NO\n"); }''',
        '字符均小写，输出要求大写YES/NO。每组重新清空队列和标记。', complexity=r'每组时间、空间均为 $O(nm)$。')
    put(15665, 1600, ['Dijkstra', '网格', '最短路'], '四方向一步耗时1，可选单向传送耗时3，避开陷阱到终点。',
        '把每个非陷阱格看成图结点，普通四邻边权1，传送边权3。传送可以不用，多个入口、出口也可共处同一格，因此保留全部普通边和合法传送边。用Dijkstra求最短时间，过期堆记录跳过。传送入口或出口是陷阱时，这条边不能使用。',
        r'''int n, m, q; while (cin >> n >> m >> q) { vector<string> grid(n); int start = 0, target = 0; for (int r = 0; r < n; r++) { cin >> grid[r]; for (int c = 0; c < m; c++) { if (grid[r][c] == 'S') start = r * m + c; if (grid[r][c] == 'T') target = r * m + c; } } vector<vector<int>> portals(n * m); while (q--) { int a, b, c, d; cin >> a >> b >> c >> d; if (grid[a][b] != '#' && grid[c][d] != '#') portals[a * m + b].push_back(c * m + d); } const int inf = 1000000000; vector<int> distance(n * m,inf); priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> heap; distance[start] = 0; heap.push({0,start}); int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1};
        while (!heap.empty()) { auto [cost,u] = heap.top(); heap.pop(); if (cost != distance[u]) continue; if (u == target) break; auto relax = [&](int v, int w) { if (distance[v] > cost + w) { distance[v] = cost + w; heap.push({distance[v],v}); } }; int r = u / m, c = u % m; for (int d = 0; d < 4; d++) { int rr = r + dr[d], cc = c + dc[d]; if (rr >= 0 && rr < n && cc >= 0 && cc < m && grid[rr][cc] != '#') relax(rr * m + cc,1); } for (int v : portals[u]) relax(v,3); } cout << (distance[target] == inf ? -1 : distance[target]) << '\n'; }''',
        '坐标从0开始，传送是单向且要3秒，不可以用普通BFS把所有边视为一步。', complexity=r'记 $V=nm$，时间 $O((V+q)\log V)$，空间 $O(V+q)$。')
